import React from 'react';

export function Skeleton({ width = '100%', height = '16px' }: { width?: string; height?: string }) {
  return (
    <div aria-busy="true" role="status" style={{
      width,
      height,
      borderRadius: '{{token:spacing.card.borderRadius}}',
      background: '{{token:colors.glass.tint}}',
      animation: 'og-pulse 1.2s ease-in-out infinite',
    }} />
  );
}

